// ===========================================================================
//  CONFIGURATION -- the only node you must edit.
// ===========================================================================
//  Secrets: set these as n8n environment variables (recommended) or paste
//  them literally below. In n8n, $env.NAME reads a host environment variable.
// ===========================================================================

const config = {
  geminiApiKey:    $env.GEMINI_API_KEY    || 'PASTE_GEMINI_API_KEY',
  callmebotApiKey: $env.CALLMEBOT_APIKEY  || 'PASTE_CALLMEBOT_APIKEY',
  whatsappPhone:   $env.WHATSAPP_PHONE    || '+201234567890',

  // Gemini model chain is handled by the HTTP node URL; change it there.
  matchThreshold: 75,
  evalBatchSize: 8,
  maxAlertsPerRun: 12,
  maxJobAgeDays: 21,

  // Paste your CV as plain text (Settings > Variables works too).
  cvText: $env.CV_TEXT || `PASTE YOUR CV TEXT HERE.
Replace this with the full plain text of your CV. The AI scores every job
against exactly this text, so the more complete it is, the better the scoring.`,

  // Public Telegram channels (no credentials needed -- t.me/s/ web preview).
  telegramChannels: [
    'telecomcareers',
    'FreeJobsInDubai',
    'gulfjobexpress',
    'qatarjobsvacancy',
    'gulfwalkins',
  ],

  // LinkedIn public guest search: keyword + location pairs.
  linkedinQueries: [
    { keywords: 'VoIP Engineer',                 location: 'United Arab Emirates' },
    { keywords: 'VoIP Engineer',                 location: 'Saudi Arabia' },
    { keywords: 'SIP Engineer OR Telephony',     location: 'United Arab Emirates' },
    { keywords: 'IT Application Support Engineer', location: 'United Arab Emirates' },
    { keywords: 'IT Application Support Engineer', location: 'Egypt' },
    { keywords: 'Unified Communications Engineer', location: 'Saudi Arabia' },
    { keywords: 'PBX Asterisk Issabel',          location: 'Egypt' },
    { keywords: 'Odoo Support Consultant',       location: 'United Arab Emirates' },
  ],

  // Tanqeeb: the largest Arab-world board that still serves bots, and the only
  // source here that searches natively in Arabic. NOTE the search parameter is
  // `keywords` (PLURAL) -- every other spelling returns HTTP 200 with the
  // WRONG 20 jobs, which is invisible unless you check the results.
  tanqeebCountries: ['egypt', 'saudi', 'uae', 'qatar'],
  tanqeebTerms: ['it support', 'odoo', 'linux', 'دعم فني', 'مهندس شبكات'],

  primaryKeywords: ['voip','sip','iax','issabel','asterisk','freepbx','pbx',
    'softphone','ivr','telephony','unified communications','contact center',
    'kamailio','opensips','3cx','genesys','avaya',
    'مهندس اتصالات','سنترالات','اتصالات'],
  secondaryKeywords: ['it support','application support','technical support',
    'service desk','help desk','helpdesk','sysadmin','system administrator',
    'noc','network engineer','odoo','erp','itsm','pos','point of sale','python',
    'linux','support engineer','support specialist',
    'دعم فني','شبكات','تقنيه معلومات','نقاط بيع','لينكس','مبرمج'],
  negativeKeywords: ['nurse','nursing','pharmacist','teacher','chef','waiter',
    'driver','security guard','cleaner','housekeeping','civil engineer',
    'mechanical engineer','hvac','welder','accountant','real estate'],
};

// Fan out into one item per HTTP request the next nodes must make.
const requests = [];

for (const q of config.linkedinQueries) {
  const url = 'https://www.linkedin.com/jobs-guest/jobs/api/seeMoreJobPostings/search'
    + '?keywords=' + encodeURIComponent(q.keywords)
    + '&location=' + encodeURIComponent(q.location)
    + '&f_TPR=r604800&sortBy=DD&start=0';
  requests.push({ json: { kind: 'linkedin', url, config, meta: q } });
}

for (const ch of config.telegramChannels) {
  requests.push({
    json: { kind: 'telegram', url: 'https://t.me/s/' + ch, config, meta: { channel: ch } },
  });
}

for (const country of config.tanqeebCountries) {
  for (const term of config.tanqeebTerms) {
    const url = 'https://' + country + '.tanqeeb.com/jobs/search'
      + '?keywords=' + encodeURIComponent(term) + '&search_period=14';
    requests.push({ json: { kind: 'tanqeeb', url, config, meta: { country, term } } });
  }
}

return requests;

// ===========================================================================
//  PARSE -- turn raw HTML into normalised job records.
//  Uses regex rather than a DOM library so it runs on stock n8n with no
//  extra npm modules enabled.
// ===========================================================================

const out = [];

function stripTags(s) {
  return (s || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

// Fold Arabic orthography, so "\u0623\u062E\u0635\u0627\u0626\u064A \u062F\u0639\u0645 \u0641\u0646\u064A" and "\u0627\u062E\u0635\u0627\u0626\u064A \u062F\u0639\u0645 \u0641\u0646\u0649" -- the same
// role written two ways on two boards -- collapse to ONE fingerprint and
// therefore ONE alert. Mirrors normalise_text() in the Python build.
function foldArabic(s) {
  return (s || '')
    .normalize('NFKD')
    .replace(/[\u064B-\u065F\u0670]/g, '')                 // harakat
    .replace(/\u0640/g, '')                                // tatweel
    .replace(/[\u0622\u0623\u0625\u0671]/g, '\u0627')      // alef variants
    .replace(/\u0629/g, '\u0647')                          // teh marbuta -> heh
    .replace(/\u0649/g, '\u064A');                         // alef maksura -> yeh
}

function fingerprint(company, title, location) {
  const basis = foldArabic(company + '|' + title + '|' + location)
    .toLowerCase().replace(/[^a-z0-9\u0600-\u06FF ]+/g, ' ').replace(/\s+/g, ' ').trim();
  let h = 0;
  for (let i = 0; i < basis.length; i++) {
    h = ((h << 5) - h) + basis.charCodeAt(i);
    h |= 0;
  }
  return 'fp' + Math.abs(h).toString(36) + '_' + basis.length;
}

for (const item of $input.all()) {
  const kind = item.json.kind;
  const html = typeof item.json.data === 'string' ? item.json.data : (item.json.body || '');
  const config = item.json.config;
  const meta = item.json.meta || {};

  if (!html) continue;

  if (kind === 'linkedin') {
    // Each result card is an <li> containing h3 (title), h4 (company),
    // .job-search-card__location, <time datetime>, and an anchor.
    const cards = html.split(/<li[\s>]/i).slice(1);
    for (const card of cards) {
      const title = stripTags((card.match(/<h3[^>]*>([\s\S]*?)<\/h3>/i) || [])[1]);
      if (!title) continue;
      const company = stripTags((card.match(/<h4[^>]*>([\s\S]*?)<\/h4>/i) || [])[1]);
      const location = stripTags(
        (card.match(/job-search-card__location"[^>]*>([\s\S]*?)</i) || [])[1]
      );
      const link = ((card.match(/href="(https:\/\/[a-z]{0,3}\.?linkedin\.com\/jobs\/view\/[^"?]+)/i) || [])[1] || '');
      const posted = (card.match(/datetime="([^"]+)"/i) || [])[1] || '';

      out.push({ json: {
        source: 'linkedin',
        title, company, location,
        url: link,
        description: '',
        posted_at: posted,
        fingerprint: fingerprint(company, title, location),
        config,
      }});
    }
  }

  if (kind === 'tanqeeb') {
    // Cards carry an <h2> title plus company/location spans. A zero-result
    // search returns UNRELATED filler rather than nothing, so every card must
    // echo a token from the query before it is emitted.
    const tokens = foldArabic(String(meta.term || '')).toLowerCase()
      .split(/\s+/).filter(t => t.length >= 3 && t !== 'the' && t !== 'and');
    const blocks = html.split(/class="[^"]*search-job-card[^"]*"/i).slice(1);
    for (const b of blocks) {
      const title = stripTags((b.match(/<h2[^>]*>([\s\S]*?)<\/h2>/i) || [])[1]);
      if (!title) continue;
      const plain = foldArabic(stripTags(b.slice(0, 1200))).toLowerCase();
      if (tokens.length && !tokens.some(t => plain.includes(t))) continue;

      const company = stripTags((b.match(/class="[^"]*company[^"]*"[^>]*>([\s\S]*?)</i) || [])[1]);
      const location = stripTags((b.match(/class="[^"]*location[^"]*"[^>]*>([\s\S]*?)</i) || [])[1]);
      const href = (b.match(/href="(\/[^"]+\.html)"/i) || [])[1] || '';
      out.push({ json: {
        source: 'tanqeeb:' + (meta.country || 'unknown'),
        title, company,
        location: location || meta.country || '',
        url: href ? 'https://' + meta.country + '.tanqeeb.com' + href : '',
        description: '',
        posted_at: '',
        fingerprint: fingerprint(company, title, location),
        config,
      }});
    }
  }

  if (kind === 'telegram') {
    const channel = meta.channel || 'unknown';
    // Each post: <div class="tgme_widget_message_text ...">TEXT</div>
    const re = /<div class="tgme_widget_message_text[^"]*"[^>]*>([\s\S]*?)<\/div>/gi;
    const times = [...html.matchAll(/<time datetime="([^"]+)"/gi)].map(m => m[1]);
    let m, i = 0;
    while ((m = re.exec(html)) !== null) {
      const text = stripTags(m[1].replace(/<br\s*\/?>/gi, '\n'));
      i++;
      if (text.length < 40) continue;
      if (!/(hiring|vacanc|job|position|opening|required|apply|recruit|مطلوب|وظيف|وظائف|فرصة)/i.test(text)) continue;

      const firstLine = text.split('\n')[0].slice(0, 180) || text.slice(0, 180);
      const extLink = (text.match(/https?:\/\/[^\s<>"']+/) || [])[0] || ('https://t.me/' + channel);

      out.push({ json: {
        source: 'telegram:' + channel,
        title: firstLine,
        company: '',
        location: '',
        url: extLink,
        description: text.slice(0, 3000),
        posted_at: times[i - 1] || '',
        fingerprint: fingerprint('', firstLine, ''),
        config,
      }});
    }
  }
}

return out;

// ===========================================================================
//  DEDUPLICATE + PRE-FILTER
//  Deduplication uses n8n's persistent workflow static data, so it survives
//  across executions exactly like the Python build's SQLite database.
// ===========================================================================

const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.seen)) store.seen = [];
if (!store.alerted) store.alerted = {};

const seen = new Set(store.seen);
const items = $input.all();
const config = items.length ? items[0].json.config : null;
if (!config) return [];

// Same Arabic folding as the parser, so bilingual keywords actually match.
function norm(s) {
  return (s || '')
    .normalize('NFKD')
    .replace(/[\u064B-\u0670\u065F]/g, '').replace(/\u0640/g, '')
    .replace(/[\u0622\u0623\u0625\u0671]/g, '\u0627')
    .replace(/\u0629/g, '\u0647').replace(/\u0649/g, '\u064A')
    .toLowerCase().replace(/[^a-z0-9\u0600-\u06FF ]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function hits(text, list) {
  let n = 0;
  for (const term of list) if (text.includes(term)) n++;
  return n;
}

const fresh = [];
const batchSeen = new Set();

for (const item of items) {
  const j = item.json;
  const fp = j.fingerprint;

  if (!fp || seen.has(fp) || batchSeen.has(fp)) continue;
  batchSeen.add(fp);

  // Age gate -- skip anything older than maxJobAgeDays.
  if (j.posted_at) {
    const ts = Date.parse(j.posted_at);
    if (!isNaN(ts)) {
      const ageDays = (Date.now() - ts) / 86400000;
      if (ageDays > config.maxJobAgeDays) continue;
    }
  }

  const blob = norm([j.title, j.company, j.location, j.description].join(' '));
  if (hits(blob, config.negativeKeywords) > 0) continue;

  const score = 3 * hits(blob, config.primaryKeywords)
              + 1 * hits(blob, config.secondaryKeywords)
              + 2 * hits(norm(j.title), config.primaryKeywords);
  if (score < 2) continue;

  j.prefilter_score = score;
  fresh.push({ json: j });
}

// Record everything we are about to evaluate so the next run skips it.
for (const f of fresh) seen.add(f.json.fingerprint);
store.seen = Array.from(seen).slice(-8000);   // bounded, keeps static data small

fresh.sort((a, b) => b.json.prefilter_score - a.json.prefilter_score);

// Group into Gemini batches -- one item per API call.
const batchSize = config.evalBatchSize || 8;
const batches = [];
for (let i = 0; i < fresh.length; i += batchSize) {
  batches.push({ json: {
    config,
    jobs: fresh.slice(i, i + batchSize).map(f => f.json),
    batchIndex: batches.length,
  }});
}

return batches;

// ===========================================================================
//  BUILD THE GEMINI REQUEST (strict JSON schema, batched)
// ===========================================================================

const out = [];

const SYSTEM = `You are a precise technical recruiter screening job postings for ONE candidate.
You receive the candidate's CV and a numbered batch of postings, some scraped from messy
sources (Telegram, RSS) that may be in Arabic or English.
Return exactly one evaluation object per posting, echoing its job_index.

SCORING RUBRIC:
  90-100  Bullseye: core VoIP/SIP/PBX/telephony or IT application support, right level, target location.
  75-89   Strong: most core requirements met, minor learnable gaps. THIS IS THE ALERT THRESHOLD.
  50-74   Adjacent role, missing differentiators, or wrong seniority.
  25-49   Same industry, wrong discipline.
  0-24    Irrelevant, or not a genuine single vacancy.

HARD RULES:
  * Score the candidate's ACTUAL EVIDENCE, not the role's prestige.
  * A role demanding 8+ years senior/lead/principal experience must not exceed 60.
  * Listing pages, search-results pages, CVs/profiles, adverts, news: is_real_job=false, match_score=0.
  * why_matched must name the concrete overlapping technologies -- never generic filler.
  * skill_gaps lists real specific missing requirements; empty array if none.
  * Translate Arabic postings and answer in English.`;

for (const item of $input.all()) {
  const { config, jobs, batchIndex } = item.json;

  const blocks = jobs.map((j, i) =>
    `### JOB ${i}\nsource: ${j.source}\ntitle: ${j.title || 'unknown'}\n` +
    `company: ${j.company || 'unknown'}\nlocation: ${j.location || 'unknown'}\n` +
    `url: ${j.url || 'none'}\nposted: ${j.posted_at || 'unknown'}\n` +
    `description: ${(j.description || '(none provided)').slice(0, 1400)}`
  ).join('\n');

  const prompt = `=== CANDIDATE CV ===\n${config.cvText}\n\n` +
    `=== JOB POSTINGS TO EVALUATE (${jobs.length}) ===\n${blocks}\n\n` +
    `Return exactly ${jobs.length} evaluation objects, one per JOB index 0-${jobs.length - 1}.`;

  out.push({ json: {
    config, jobs, batchIndex,
    geminiBody: {
      systemInstruction: { parts: [{ text: SYSTEM }] },
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: {
        responseMimeType: 'application/json',
        temperature: 0.15,
        maxOutputTokens: 8192,
        responseSchema: {
          type: 'OBJECT',
          properties: {
            evaluations: {
              type: 'ARRAY',
              items: {
                type: 'OBJECT',
                properties: {
                  job_index:    { type: 'INTEGER' },
                  is_real_job:  { type: 'BOOLEAN' },
                  company_name: { type: 'STRING' },
                  role_title:   { type: 'STRING' },
                  location:     { type: 'STRING' },
                  match_score:  { type: 'INTEGER' },
                  why_matched:  { type: 'STRING' },
                  skill_gaps:   { type: 'ARRAY', items: { type: 'STRING' } },
                },
                required: ['job_index','is_real_job','company_name','role_title',
                           'location','match_score','why_matched','skill_gaps'],
              },
            },
          },
          required: ['evaluations'],
        },
      },
      safetySettings: [
        'HARM_CATEGORY_HARASSMENT','HARM_CATEGORY_HATE_SPEECH',
        'HARM_CATEGORY_SEXUALLY_EXPLICIT','HARM_CATEGORY_DANGEROUS_CONTENT',
      ].map(c => ({ category: c, threshold: 'BLOCK_ONLY_HIGH' })),
    },
  }});
}

return out;

// ===========================================================================
//  READ GEMINI'S VERDICT -> keep only genuine high matches -> format alerts
// ===========================================================================

const store = $getWorkflowStaticData('global');
if (!store.alerted) store.alerted = {};

const matches = [];

for (const item of $input.all()) {
  let config, jobs;
  try {
    // The paired input carries the batch context alongside Gemini's response.
    const paired = $('Build Gemini Request').all()[item.pairedItem?.item ?? 0];
    config = paired.json.config;
    jobs   = paired.json.jobs;
  } catch (e) {
    continue;
  }

  const raw = item.json?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!raw) continue;

  let parsed;
  try { parsed = JSON.parse(raw); } catch (e) { continue; }

  for (const ev of (parsed.evaluations || [])) {
    const idx = Number(ev.job_index);
    const job = jobs[idx];
    if (!job) continue;
    if (ev.is_real_job === false) continue;

    const score = Math.max(0, Math.min(100, parseInt(ev.match_score, 10) || 0));
    if (score < config.matchThreshold) continue;
    if (store.alerted[job.fingerprint]) continue;   // never alert twice

    store.alerted[job.fingerprint] = new Date().toISOString();

    // The model must never invent the link or the source -- take ours.
    const gaps = Array.isArray(ev.skill_gaps) ? ev.skill_gaps.join(', ') : '';
    const lines = [
      `\u{1F6A8} *NEW HIGH-MATCH JOB FOUND* (Score: ${score}%)`,
      `\u{1F3E2} *Company:* ${ev.company_name || job.company || 'Unknown'}`,
      `\u{1F4CD} *Location:* ${ev.location || job.location || 'Unknown'}`,
      `\u{1F4BC} *Role:* ${ev.role_title || job.title || 'Unknown'}`,
      `\u{1F517} *Link:* ${job.url || '(no direct link)'}`,
      `\u{1F4E1} *Source:* ${job.source}`,
    ];
    if (ev.why_matched) lines.push(`\u2705 *Why You Match:* ${String(ev.why_matched).slice(0, 420)}`);
    if (gaps)           lines.push(`\u26A0\uFE0F *Gaps to address:* ${gaps.slice(0, 220)}`);

    matches.push({ json: {
      match_score: score,
      company_name: ev.company_name || job.company || 'Unknown',
      role_title: ev.role_title || job.title || 'Unknown',
      location: ev.location || job.location || 'Unknown',
      source_platform: job.source,
      direct_link: job.url,
      why_matched: ev.why_matched || '',
      skill_gaps: ev.skill_gaps || [],
      messageText: lines.join('\n').slice(0, 900),
      config,
    }});
  }
}

// Best first, then apply the per-run alert cap.
matches.sort((a, b) => b.json.match_score - a.json.match_score);
const cap = matches.length ? matches[0].json.config.maxAlertsPerRun : 12;
return matches.slice(0, cap);
